  LanguageConfig_ExchangeShopRules_CN = {
    Text = [[
<Title:Negozio di Scambio>
: I Custodi possono scambiare oggetti presso i vari Negozi di Scambio spendendo la valuta corrispondente.
: Quando il Livello d'Indagine di un Custode aumenta, il Negozio di Scambio si aggiorna di conseguenza e sblocca nuovi contenuti.
