    Text = "I poemi portano con sé le proprie emozioni, così come i fiori portano con sé i propri significati. Questo è per te."
  },
  LanguageConfig_LotteryPhoneticDialogue13_CN = {
    Text = "Ecco, continuerò a combattere in eterno."
