  LanguageConfig_LotteryPhoneticDialogue14_CN = {
    Text = "Sei venuto ad assistere al mio trionfo?"
  },
  LanguageConfig_LotteryPhoneticDialogue15_CN = {
    Text = "Dibattiti pure quanto vuoi, mia cara. Vuoi che l'insegnante ti dia una carezza sulla testa?"
