  LanguageConfig_LotteryPhoneticDialogue17_CN = {
    Text = "Oh, sei stato piuttosto fortunato, caro cliente. Vuoi riprovare?"
  },
  LanguageConfig_LotteryPhoneticDialogue18_CN = {
    Text = "Vuoi dare un'altra occhiata? Il mio negozio ha in serbo oggetti ancora più preziosi."
