  LanguageConfig_LotteryPhoneticDialogue19_CN = {
    Text = "Questo rapporto è alquanto delizioso. Grazie per il banchetto."
  },
  LanguageConfig_LotteryPhoneticDialogue1_CN = {
    Text = "Grazie per la tua gentilezza, caro."
  },
  LanguageConfig_LotteryPhoneticDialogue20_CN = {
    Text = "Mm, lo prendo. Altro?"
  },
  LanguageConfig_LotteryPhoneticDialogue21_CN = {
    Text = "Grazie per il tuo dono. Ti prego, accetta questi in cambio."
  },
  LanguageConfig_LotteryPhoneticDialogue22_CN = {
    Text = "Ho trovato dei materiali rari. Spero ti siano utili."
  },
  LanguageConfig_LotteryPhoneticDialogue23_CN = {
    Text = "Un semplice antipasto, bon appétit."
  },
  LanguageConfig_LotteryPhoneticDialogue24_CN = {
    Text = "Questo piatto è stato preparato dalle mani stesse di Sua Maestà. Ci auguriamo che soddisfi il vostro palato."
  },
  LanguageConfig_LotteryPhoneticDialogue25_CN = {
    Text = "Non farti ossessionare da tecniche e regole."
