  LanguageConfig_LotteryPhoneticDialogue29_CN = {
    Text = "Ho visto i veri colori. Che magnificenza."
  },
  LanguageConfig_LotteryPhoneticDialogue2_CN = {
    Text = "Oh, che fortuna meravigliosa! Abbine gran cura."
  },
  LanguageConfig_LotteryPhoneticDialogue30_CN = {
    Text = "Follia e assurdità sono la bellezza della realtà e la bellezza dell'arte!"
