  LanguageConfig_LotteryPhoneticDialogue33_CN = {
    Text = [[
Ehi, Custode! Anche se le cose fossero andate esattamente allo stesso modo, mi avresti salvata comunque, vero?
...Allora posso dormire tranquilla. Gr-ehm, voglio dire, grazie.]]
  },
  LanguageConfig_LotteryPhoneticDialogue34_CN = {
    Text = "Ultimamente sogno il passato di continuo. Mi sta facendo impazzire. Spero che questo sia utile."
  },
  LanguageConfig_LotteryPhoneticDialogue35_CN = {
    Text = "La Madre Divina ha compiuto un nobile sacrificio per Lemuria, e noi siamo disposti a dare tutto in cambio della sua pace."
  },
  LanguageConfig_LotteryPhoneticDialogue36_CN = {
    Text = "Grazie per il tuo tributo alla Madre Divina; mi auguro che questo le conceda un sonno sereno."
  },
  LanguageConfig_LotteryPhoneticDialogue37_CN = {
    Text = "Questo sogno continuerà a ripetersi senza fine, e tu...\nSii grato: ti concederò di farne parte."
  },
  LanguageConfig_LotteryPhoneticDialogue38_CN = {
    Text = "Hai mai visto come sono i miei sogni? Quel genere di lordura, corrotta fino al midollo..."
  },
  LanguageConfig_LotteryPhoneticDialogue39_CN = {
    Text = "Quanto sono superflui i Beni Terreni. Se hai un desiderio, perché non sussurrarlo direttamente a me...?"
  },
  LanguageConfig_LotteryPhoneticDialogue3_CN = {
    Text = "Hai davvero trovato l'oro, ragazzo! Ogni cosa nel mio Negozio è una Reliquia antica!"
  },
  LanguageConfig_LotteryPhoneticDialogue40_CN = {
    Text = "Se vi trovaste tra le rovine desolate dell'Estremo Oriente, fate attenzione — non offrite culto con leggerezza. Fantasmi o demoni? Heh... quelli non meritano nemmeno menzione."
  },
  LanguageConfig_LotteryPhoneticDialogue41_CN = {
    Text = "Coalsie, la migliore!"
  },
  LanguageConfig_LotteryPhoneticDialogue42_CN = {
    Text = "Coalsie, fantastico!"
  },
  LanguageConfig_LotteryPhoneticDialogue43_CN = {
    Text = "Luccicante! Per te, Coalsie!"
  },
  LanguageConfig_LotteryPhoneticDialogue44_CN = {
    Text = "Amico, piace! Vortice, Coalsie, scambio!"
  },
  LanguageConfig_LotteryPhoneticDialogue45_CN = {
    Text = "Conchiglia, così bella! Vortice, raccogliere! Coalsie, premi!"
  },
  LanguageConfig_LotteryPhoneticDialogue46_CN = {
    Text = "Vortice, piace! Grazie, Coalsie!"
  },
  LanguageConfig_LotteryPhoneticDialogue47_CN = {
    Text = "Esatto... Tu che sei stato abbandonato dal destino, ora infrangi la sua gabbia!"
  },
  LanguageConfig_LotteryPhoneticDialogue48_CN = {
    Text = "Ah, un piccolo scherzo crudele del Destino."
  },
  LanguageConfig_LotteryPhoneticDialogue49_CN = {
    Text = "Riproduzione, crescita, tutte queste cose sono strettamente legate all'amore."
