Penso che sia una cosa meravigliosa.]]
  },
  LanguageConfig_LotteryPhoneticDialogue52_CN = {
    Text = "L'amore degli esseri umani... no, l'amore di tutti gli esseri viventi è davvero meraviglioso.\nUn'esistenza più importante di sé stessi, più importante di qualsiasi altra cosa."
  },
  LanguageConfig_LotteryPhoneticDialogue53_CN = {
    Text = "Ti prego, attendi insieme a me l'inizio di quel mondo splendente, radioso e meraviglioso."
