  LanguageConfig_RailWayStageCrazyMileExpGetDesc_CN = {
    Text = "Punti VIP massimi disponibili per questa operazione: {s1}. \nGnosi d'emergenza utilizzata: {s3}. Attualmente guadagnati: {s2} Punti VIP. \n ·Fase 1: la vittoria contro Élite/Boss garantisce 25/75 Punti VIP. \n ·Fase 2: la vittoria contro Élite/Boss garantisce 50/150 Punti VIP. \n ·Fase 3: la vittoria contro Élite/Boss garantisce 75/225 Punti VIP. \n ·La difficoltà Difficile/Follia aumenta i Punti VIP guadagnati del 150%/400%. \n ·Ogni utilizzo della Gnosi d'emergenza riduce i Punti VIP del 20%."
