  LanguageConfig_RailWayStageDifficultyBuffContent1_CN = {
    Text = "<Title:Ricompense di Fase>\nPrima Fase: Sconfiggi l'Élite/Boss per ottenere \"Punti VIP\" ×25/75 \nSeconda Fase: Sconfiggi l'Élite/Boss per ottenere \"Punti VIP\" ×50/150 \nTerza Fase: Sconfiggi l'Élite/Boss per ottenere \"Punti VIP\" ×75/225\n<Title:Reliquie Iniziali>\nOttieni \"Fotocamera Immacolata della Piccola N\" all'inizio.\n<OrangeQuality:Armonia Dorata>: \"Armonia di Arithmetica\" ora aumenta il Costo di Arithmetica solo di 1. Ogni 1% di Amplificazione del Danno aumenta la Profondità della Ricerca Occulta dell'1%.\n<RedQuality:Fatica del Transito>: Effetti di Guarigione -50% in battaglia."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent2_CN = {
    Text = "<Title:Regole Speciali>\nMaggiore è la difficoltà, più Punti VIP otterrai. Se hai completato tutte e tre le Fasi, Punti VIP +150%.\n<Title:Reliquie Iniziali>\nOttieni \"Fotocamera Logora di Piccolo N\" all'inizio.\n<OrangeQuality:Armonia Dorata>: \"Armonia di Arithmetica\" ora aumenta il Costo di Arithmetica solo di 1. Ogni 1% di Amplificazione del Danno aumenta la Profondità della Ricerca Occulta dell'1%.\n<OrangeQuality:Dono Dimensionale>: Ottieni 1 Reliquia Dimensionale casuale all'inizio. Limite Mano +1.\n<RedQuality:Fatica da Transito>: Guarigione -50% in battaglia.\n<RedQuality:Vertigine da Movimento>: Inizi la battaglia con -50% Aliemus/Keyflare."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3V2_CN = {
    Text = "<Title:Sfida Speciale>\nIn Difficoltà Follia, dopo aver completato la terza fase si affronterà in aggiunta il Boss finale della quarta fase \"Tawil\".\n<Title:Ricompense dello Stadio>\nPiù alta è la difficoltà affrontata, più \"Punti VIP\" si otterranno. I \"Punti VIP\" ottenuti completando le tre fasi aumentano del 400%\nDopo aver sconfitto il Boss finale \"Tawil\", si ottengono \"Punti VIP\" × 1500 aggiuntivi.\n<Title:Reliquie Iniziali>\nAll'inizio dell'indagine si ottiene la Reliquia \"Fotocamera Caotica di Little N\"\n·<OrangeQuality:Armonia Dorata>: l'effetto di aumento dell'Arithmetica apportato dall'\"Armonia di Arithmetica\" è al massimo 1 punto; ogni 1% di Amplificazione del Danno posseduta aumenta l'effetto della Ricerca Occulta dell'1%.\n·<OrangeQuality:Dono Dimensionale>: all'inizio dell'esplorazione, si ottiene casualmente 1 Reliquia Immagine Dimensionale e il Limite Massima della Mano aumenta di 2.\n·<OrangeQuality:Rito Benedetto>: le ricompense per aver sconfitto i Boss della prima e della seconda fase vengono cambiate in 1 Reliquia Benedetta a scelta tra 3 casuali.\n·<RedQuality:Affaticamento da transito>: durante il combattimento, tutti gli effetti di Guarigione della Vita si riducono del 50%.\n·<RedQuality:Vertigine Cinetica>: all'inizio del combattimento, l'Aliemus corrente e l'Energia-S di tutti i Risvegliatori si riducono del 50%.\n·<RedQuality:Ferrovia Sempiterna>: all'inizio dell'esplorazione, l'Aliemus Base e il limite massimo di Energia-S di tutti i Risvegliatori aumentano del 50%"
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3_CN = {
    Text = "<Title:Regole Speciali>\nPiù alta è la difficoltà, più Punti VIP otterrai. Se hai completato tutte e tre le Fasi, Punti VIP +400%.\n<Title:Reliquie Iniziali>\nOttieni \"Caotica Fotocamera della Piccola N\" all'inizio.\n<OrangeQuality:Armonia Dorata>: \"Armonia di Arithmetica\" ora aumenta il Costo di Arithmetica solo di 1. Ogni 1% di Amplificazione del Danno aumenta la Profondità della Ricerca Occulta dell'1%.\n<OrangeQuality:Rituale Benedetto>: I Boss di Fase rilasciano una Reliquia Benedetta a 3 scelte.\n<OrangeQuality:Dono Dimensionale>: Ottieni 1 Reliquia Dimensionale casuale all'inizio. Limite di Mano +1.\n<RedQuality:Ferrovia della Notte Eterna>: Aliemus Base/Limite Keyflare +100%.\n<RedQuality:Fatica del Transito>: Guarigione -50%.\n<RedQuality:Vertigine da Movimento>: Inizia la battaglia con -50% Aliemus/Keyflare."
