  LanguageConfig_ReplayTabRule_CN = {
    Text = "<Title:\"Modalità Indagine\">\n Dopo aver completato le indagini nelle azioni di Indagine, nel regno senza luce e negli eventi di gioco a tempo limitato, i relativi registri d'indagine possono essere consultati qui.\n Le sfide fallite nella modalità indagine non verranno registrate.\n Attualmente è supportata solo la riproduzione dell'ultima battaglia del livello.\n\n<Title:\"Replay\">\n Puoi inserire i registri di battaglia nella casella sottostante per visualizzare i replay delle battaglie corrispondenti.\n I registri di battaglia possono essere copiati e condivisi con altri dalle interfacce \"Dati d'Indagine\" della modalità indagine e \"Insediamento Battaglia\" del Traphase.\n \"Azioni d'Indagine\" e \"Traphase\" possono salvare ciascuno fino a 100 registri, conservati per un massimo di 30 giorni."
  },
