  LanguageConfig_ReturnEventRewardSenderText_CN = {Text = "Doll"},
  LanguageConfig_ReturnEventRewardText_CN = {
    Text = "La missione di combattere la Dissoluzione è una strada a senso unico verso l'ignoto, disseminata di trappole e pericoli.\n\"Salvare il mondo\" è una causa troppo grande — e in cui è fin troppo facile perdersi. Nel corso della storia dell'Università di Mythag, molti giovani Investigatori sono stati sedotti dal proprio senso del dovere, consumandosi oltre ogni ragionevolezza.\nSiamo tutti sollevati che tu abbia scelto di prenderti una pausa. Non possiamo permetterci di perdere un altro Custode.\nMa basta con le formalità. Per aiutarti a riprendere le indagini il più rapidamente possibile, ho preparato un piano di addestramento di reinserimento. Seguilo fino in fondo, portami i risultati e avrai le tue ricompense.\nInoltre, Ramona ha preparato alcuni \"piccoli doni\" per te. Le sei mancato parecchio."
  },
