  LanguageConfig_StorylineGuide_0_CN = {
    Text = "Viviamo per morire."
  },
  LanguageConfig_StorylineGuide_10_CN = {
    Text = "L'entropia è la conclusione ultima. Ciononostante, vi è chi rifiuta di abbandonare la propria sfida."
  },
  LanguageConfig_StorylineGuide_11_CN = {
    Text = "Non osare volgere lo sguardo al cosmo lassù. Non osare volgere lo sguardo all'abisso interiore."
  },
  LanguageConfig_StorylineGuide_12_CN = {
    Text = "Banchettare è l'unica virtù di questo mondo."
  },
  LanguageConfig_StorylineGuide_13_CN = {
    Text = "Non vi sono risposte nel sogno sconfinato. È tempo di risvegliarsi."
  },
  LanguageConfig_StorylineGuide_14_CN = {
    Text = "Sul palcoscenico del fato, non scegliamo mai i ruoli che interpretiamo."
  },
  LanguageConfig_StorylineGuide_15_CN = {
    Text = "O Viaggiatori, camminate dolcemente in quella notte innevata. Sulla vetta delle volontà annullate, possiate testimoniare la fine di un grande sogno."
  },
  LanguageConfig_StorylineGuide_16_CN = {
    Text = "Statistica principale scelta casualmente tra Tasso Crit., Danno Crit., Livello di Ricarica della Chiave d'Argento o Livello Ricarica Aliemus."
  },
  LanguageConfig_StorylineGuide_17_CN = {
    Text = "Statistica principale scelta casualmente tra Tasso Crit., Danno Crit., Livello di Ricarica della Chiave d'Argento o Livello Ricarica Aliemus."
  },
  LanguageConfig_StorylineGuide_18_CN = {
    Text = "Statistica principale scelta casualmente tra Tasso Crit., Danno Crit., Livello di Ricarica della Chiave d'Argento o Livello Ricarica Aliemus."
  },
  LanguageConfig_StorylineGuide_19_CN = {
    Text = "Statistica principale scelta casualmente tra Tasso Crit., Danno Crit., Livello di Ricarica della Chiave d'Argento o Livello Ricarica Aliemus."
  },
  LanguageConfig_StorylineGuide_1_CN = {
    Text = "Addèntrati nelle insidiose nebbie notturne di Londinium, Custode. Il tuo cammino ha inizio qui."
  },
  LanguageConfig_StorylineGuide_20_CN = {
    Text = "Statistica principale scelta casualmente tra Tasso Crit., Danno Crit., Livello di Ricarica della Chiave d'Argento o Livello Ricarica Aliemus."
  },
  LanguageConfig_StorylineGuide_2_CN = {
    Text = "Artisti, folli, asceti, stolti... Questa città è la tua galleria. Qui, sulla soglia delle loro storie, le figure di cera anelano al tuo arrivo."
  },
  LanguageConfig_StorylineGuide_3_CN = {
    Text = "Le nevi di Rye aborrono la carneficina. Lei ti attende, cercando soltanto uno scambio. Ti offre i segreti che più brami — a un prezzo sempre crudele, eppure sempre giusto."
  },
  LanguageConfig_StorylineGuide_4_CN = {
    Text = "Ricorda. Combatti per la memoria; muori per la memoria. È il nostro vangelo e il nostro epitaffio. Al di là della memoria, non possediamo nulla."
  },
  LanguageConfig_StorylineGuide_5_CN = {
    Text = "Prima che le stelle cadessero, pregammo l'oceano: che la dolce marea ci conduca nel dormiveglia. Che possiamo fare ritorno all'abbraccio della nostra terra dei Bianchi Uccelli, perduti in un sogno che non ha mai fine."
  },
  LanguageConfig_StorylineGuide_6_CN = {
    Text = "Intona ora la cantilena — l'antico Re contempla il Suo trono ancora una volta. Il Suo sacro decreto porta il Reame Divino a ogni anima di vera fede."
  },
  LanguageConfig_StorylineGuide_7_CN = {
    Text = "Ascolta, prega, richiama, prolifera. Sottomettiti agli ideali più elevati e ai desideri più abietti. In nome della Madre, Egli sopporta attraverso il caos e la paura."
  },
  LanguageConfig_StorylineGuide_8_CN = {
    Text = "L'Eterna Lanterna è accesa. La sua fioca luce illumina il sentiero verso la tua destinazione finale."
  },
  LanguageConfig_StorylineGuide_9_CN = {
    Text = "DaLe la tua risposta."
  },
