  LanguageConfig_TrinketAutoRefine_CN = {
    Text = "<Title:Trascrizione Automatica>\nLa Trascrizione Automatica consente di eseguire trascrizioni rapidamente e in blocco.\nDurante la Trascrizione Automatica, se un risultato di trascrizione contiene 1 attributo sbloccato con intensità 8, la Trascrizione Automatica si interromperà.\nLa Trascrizione Automatica può essere eseguita fino a 100 volte.\nQuando i materiali sono insufficienti, la trascrizione si interromperà automaticamente.\n<Title:Salta>\nDurante la Trascrizione Automatica, ogni risultato di trascrizione verrà visualizzato e potrai scegliere di saltare il processo di trascrizione. Dopo aver saltato, verrà visualizzato direttamente il risultato finale della Trascrizione Automatica."
  },
  LanguageConfig_TrinketAutoSelectTips_CN = {
