  LanguageConfig_TrinketBindNoneSelectedTips_CN = {
    Text = "Nessun Patto disponibile da Vincolare. Selezionane almeno uno."
  },
  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:Vincolo del Patto>\nI Custodi possono ora legare i Patti ai Risvegliatori.\nOgni Risvegliatore dispone di 6 slot di legame (un Patto per slot).\nUna volta legato, l'attributo primario del Patto aumenta del 50%.\nI Patti legati non appariranno nel tuo Inventario né nel sistema di Alchimia.\nSe un Risvegliatore non ha nessun Patto equipaggiato in una formazione o nello slot Supporto, il suo Patto legato verrà equipaggiato automaticamente.\nPotenziare un Patto legato non scioglierà il legame; gli attributi potenziati si aggiorneranno automaticamente.\n\n<Title:Scioglimento del Vincolo del Patto>\nPer modificare o rimuovere un legame, usa l'opzione di scioglimento nella schermata del Legame del Patto.\nSciogliere un singolo slot costa 10 Patti dello stesso tipo (qualsiasi posizione di slot può essere usata come costo)."
  },
